import com.fasterxml.jackson.databind.util.NameTransformer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.InvocationTargetException;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.NoSuchElementException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class BeanPropertyMap_remove_TriageGen2Test {

    private SettableBeanProperty propA;
    private SettableBeanProperty propB;
    private SettableBeanProperty propC;

    @Before
    public void setUp() {
        propA = mock(SettableBeanProperty.class);
        when(propA.getName()).thenReturn("a");

        propB = mock(SettableBeanProperty.class);
        when(propB.getName()).thenReturn("b");

        propC = mock(SettableBeanProperty.class);
        when(propC.getName()).thenReturn("c");
    }









    @Test
    public void testRemove_WithNullInHashArea() {
        // This test targets the 'if (prop == null) continue;' branch
        // Since _hashArea is internal, we rely on the fact that 'construct' 
        // creates a populated map. To force a null in the internal array 
        // while still having other elements, we can use a map with one element.
        // The iteration logic in remove() skips indices where prop is null.

        Collection<SettableBeanProperty> props = new ArrayList<>(Arrays.asList(propA, propB));
        BeanPropertyMap map = BeanPropertyMap.construct(props, false);

        // Removing the second one should still work even if there are internal gaps/nulls
        map.remove(propB);

        assertEquals(1, map.size());
        assertNotNull(map.find("a"));
    }


}

package com.fasterxml.jackson.databind.deser.impl;

