import static org.mockito.Mockito.*;

public class BeanPropertyMap_remove_TriageGen2Test {

    private SettableBeanProperty propA;
    private SettableBeanProperty propB;
    private SettableBeanProperty propC;

    @Before
    public void setUp() {
        propA = mock(SettableBeanProperty.class);
        when(propA.getName()).thenReturn("a");

        propB = mock(SettableBeanProperty.class);
        when(propB.getName()).thenReturn("b");

        propC = mock(SettableBeanProperty.class);
        when(propC.getName()).thenReturn("c");
    }











    @Test
    public void testRemove_CaseInsensitiveMatch() {
        // The code comment mentions case-insensitivity logic.
        // If the map is constructed as case-insensitive, we check if removal works.
        Collection<SettableBeanProperty> props = new ArrayList<>(Arrays.asList(propA, propB));
        BeanPropertyMap map = BeanPropertyMap.construct(props, true);

        SettableBeanProperty propUpperA = mock(SettableBeanProperty.class);
        when(propUpperA.getName()).thenReturn("A");

        // In case-insensitive mode, finding "A" should match "a" via getPropertyName logic
        // However, the code uses key.equals(prop.getName()). 
        // If key is "A" and prop.getName() is "a", equals returns false.
        // But the implementation of getPropertyName handles the normalization.

        map.remove(propA);
        assertEquals(1, map.size());
        assertNull(map.find("a"));
    }
}
